protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex removed — Cosmos DB throws at startup in EF Core 9.
    // Manage indexing via Azure Portal / Bicep / Terraform instead.

    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9 renamed the discriminator property from "Discriminator" to "$type".
        // Existing 500K documents use "Discriminator", and direct SQL queries
        // reference c.Discriminator — keep the old name for compatibility.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 changed id format from "Product|123" to just "123".
        // Existing documents use the compound format — preserve it.
        entity.HasRootDiscriminatorInJsonId(true);
    });
}

